(()=>{const zh=document.documentElement.lang.startsWith('zh'),el=k=>document.getElementById('E04-'+k),defaults={bath:10,aliquot:2,sample:3};let p={...defaults};function rows(){let removed=0;return [20,40,60].map(total=>{const current=total-removed,c=current/p.bath,row={total,current,removed,c};removed+=p.aliquot*c;return row;});}function state(){const r=rows()[p.sample-1];return {...p,correctedUg:r.current+r.removed,bathUg:r.current,previousUg:r.removed,concentration:r.c};}function render(){for(const k of ['bath','aliquot','sample']){el(k).value=p[k];el(k+'-value').textContent=p[k];}let g='<rect width="800" height="420" fill="#faf9f5"/>';const y=v=>330-v*4.3;for(let v=0;v<=60;v+=20)g+=`<path d="M85 ${y(v)}H725" stroke="#dce4e7"/><text x="73" y="${y(v)+5}" text-anchor="end" font-size="15">${v}</text>`;rows().forEach((r,i)=>{let x=150+i*210;g+=`<rect x="${x}" y="${y(r.current)}" width="100" height="${4.3*r.current}" fill="#186e83"/><rect x="${x}" y="${y(r.total)}" width="100" height="${4.3*r.removed}" fill="#cd803f"/><text x="${x+50}" y="355" text-anchor="middle" font-size="16">${i+1}</text>`;if(i===p.sample-1)g+=`<rect x="${x-5}" y="${y(r.total)-5}" width="110" height="${4.3*r.total+10}" fill="none" stroke="#8160a1" stroke-width="3"/>`;});g+=`<text x="85" y="28" font-size="17">${zh?'蓝：当前外液；橙：此前取走；总高度：累计释放':'Blue: current bath; orange: earlier samples; total height: cumulative release'}</text><text x="400" y="402" text-anchor="middle" font-size="17">${zh?'取样序号':'Sample number'}</text><text x="25" y="210" transform="rotate(-90 25 210)" text-anchor="middle" font-size="17">${zh?'目标物质量 / μg':'Target mass / μg'}</text>`;el('plot').innerHTML=g;let s=state();el('readout').textContent=zh?`第 ${p.sample} 次：当前外液 ${s.bathUg.toFixed(2)} μg，此前取走 ${s.previousUg.toFixed(2)} μg，累计 ${s.correctedUg.toFixed(2)} μg；当前浓度 ${s.concentration.toFixed(3)} μg/mL。`:`Sample ${p.sample}: current bath ${s.bathUg.toFixed(2)} μg, earlier samples ${s.previousUg.toFixed(2)} μg, cumulative ${s.correctedUg.toFixed(2)} μg; current concentration ${s.concentration.toFixed(3)} μg/mL.`;}function set(n){if('bath'in n)p.bath=Math.min(20,Math.max(5,+n.bath));if('aliquot'in n)p.aliquot=Math.min(5,Math.max(0,+n.aliquot));if('sample'in n)p.sample=Math.round(Math.min(3,Math.max(1,+n.sample)));render();return state();}for(const k of ['bath','aliquot','sample'])el(k).addEventListener('input',()=>set({[k]:+el(k).value}));el('double').addEventListener('click',()=>set({aliquot:p.aliquot*2}));el('reset').addEventListener('click',()=>{p={...defaults};render();});window.CourseLab={set,state,reset(){p={...defaults};render();return state();}};render();})();
